import{_ as o,r as a,o as l,c as p,e as s,a as c,s as r}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Поле Relation - October CMS - 3.x","titleTemplate":false,"description":"Виджет формы","frontmatter":{"subtitle":"Виджет формы","shortname":"Relation"},"headers":[{"level":2,"title":"Применение условий","slug":"применение-условии","link":"#применение-условии","children":[{"level":3,"title":"SQL-условие запроса","slug":"sql-условие-запроса","link":"#sql-условие-запроса","children":[]},{"level":3,"title":"PHP-области запроса","slug":"php-области-запроса","link":"#php-области-запроса","children":[]}]},{"level":2,"title":"Интеграция с Relation Controller","slug":"интеграция-с-relation-controller","link":"#интеграция-с-relation-controller","children":[]}],"relativePath":"3.x/ru/element/form/widget-relation.md","filePath":"3.x/ru/element/form/widget-relation.md"}'),u={name:"3.x/ru/element/form/widget-relation.md"};function d(i,n,k,y,g,m){const e=a("pre-heading"),t=a("post-heading");return l(),p("div",null,[s(e),n[0]||(n[0]=c("h1",null,"Поле Relation",-1)),s(t),n[1]||(n[1]=r(`<p><code>relation</code> — рендерит выпадающий список или список чекбоксов в зависимости от типа отношения поля. Единичные отношения отображают выпадающий список, множественные отношения отображают список чекбоксов. Метка для отображения каждого отношения берётся из определения <code>nameFrom</code> или <code>select</code>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">categories</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Categories
    <span class="token key atrule">type</span><span class="token punctuation">:</span> relation
</code></pre></div><p>Поддерживаются и обычно используются следующие <a href="./../form-fields.html">свойства поля</a>.</p><div class="table"><table tabindex="0"><thead><tr><th>Свойство</th><th>Описание</th></tr></thead><tbody><tr><td><strong>label</strong></td><td>имя при отображении поля формы пользователю.</td></tr><tr><td><strong>comment</strong></td><td>пояснительный комментарий под полем.</td></tr><tr><td><strong>nameFrom</strong></td><td>имя атрибута модели, используемого для отображения метки отношения. По умолчанию: <code>name</code>.</td></tr><tr><td><strong>excludeFrom</strong></td><td>атрибут родительской модели, используемый для исключения связанных ключей из списка, необязательно.</td></tr><tr><td><strong>select</strong></td><td>пользовательское SQL-выражение select для имени.</td></tr><tr><td><strong>emptyOption</strong></td><td>текст для отображения, когда нет доступных вариантов.</td></tr><tr><td><strong>conditions</strong></td><td>задаёт необработанное условие where для применения к запросу модели.</td></tr><tr><td><strong>modelScope</strong></td><td>применяет метод <a href="./../../extend/database/model.html">области запроса модели</a> к <strong>связанной модели формы</strong>, может быть именем метода модели или статическим методом PHP-класса (<code>Class::method</code>).</td></tr><tr><td><strong>defaultSort</strong></td><td>устанавливает столбец сортировки и направление по умолчанию, поддерживает строку для имени столбца или массив с ключами <code>column</code> и <code>direction</code>. Направление может быть <code>asc</code> для возрастающего (по умолчанию) или <code>desc</code> для убывающего порядка.</td></tr><tr><td><strong>useController</strong></td><td>автоматически определяет, настроено ли поле с <a href="./../../extend/forms/relation-controller.html">поведением Relation Controller</a>, и использует его. По умолчанию: <code>true</code></td></tr><tr><td><strong>controller</strong></td><td>задаёт массив для ручной настройки интеграции с <a href="./../../extend/forms/relation-controller.html">поведением Relation Controller</a>.</td></tr></tbody></table></div><p>Используйте свойство <code>nameFrom</code> для настройки метки, используемой для связанной записи.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">categories</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Categories
    <span class="token key atrule">type</span><span class="token punctuation">:</span> relation
    <span class="token key atrule">nameFrom</span><span class="token punctuation">:</span> title
</code></pre></div><p>В качестве альтернативы вы можете заполнить метку с помощью пользовательского выражения <code>select</code>. Здесь работает любое допустимое SQL-выражение.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">user</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> User
    <span class="token key atrule">type</span><span class="token punctuation">:</span> relation
    <span class="token key atrule">select</span><span class="token punctuation">:</span> concat(first_name<span class="token punctuation">,</span> <span class="token string">&#39; &#39;</span><span class="token punctuation">,</span> last_name)
</code></pre></div><h2 id="применение-условии"><a href="#применение-условии" class="header-anchor">#</a> Применение условий</h2><p>Вы можете фильтровать доступные записи с помощью SQL- или PHP-условий, используя подходы ниже.</p><h3 id="sql-условие-запроса"><a href="#sql-условие-запроса" class="header-anchor">#</a> SQL-условие запроса</h3><p>Вы можете ограничить связанную модель с помощью необработанного SQL-запроса, используя свойство <code>conditions</code>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">user</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> User
    <span class="token key atrule">type</span><span class="token punctuation">:</span> relation
    <span class="token key atrule">conditions</span><span class="token punctuation">:</span> is_featured = true
</code></pre></div><p>Значение также поддерживает простые параметры, извлекаемые из атрибутов родительской модели. Имена параметров начинаются с символа двоеточия (<code>:</code>).</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">country</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Country
    <span class="token key atrule">type</span><span class="token punctuation">:</span> relation

<span class="token key atrule">state</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> State
    <span class="token key atrule">type</span><span class="token punctuation">:</span> relation
    <span class="token key atrule">dependsOn</span><span class="token punctuation">:</span> country
    <span class="token key atrule">conditions</span><span class="token punctuation">:</span> custom_country_id = <span class="token punctuation">:</span>country_id
</code></pre></div><h3 id="php-области-запроса"><a href="#php-области-запроса" class="header-anchor">#</a> PHP-области запроса</h3><p>Вы можете указать область модели для фильтрации результатов с помощью свойства <code>modelScope</code>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">user</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> User
    <span class="token key atrule">type</span><span class="token punctuation">:</span> relation
    <span class="token key atrule">modelScope</span><span class="token punctuation">:</span> withTrashed
</code></pre></div><p><code>modelScope</code> может использоваться для связывания двух связанных полей, например, связывания моделей <code>Country</code> и <code>State</code>, где доступные штаты фильтруются по выбранной стране. Свойство <code>dependsOn</code> включает <a href="./../../extend/forms/field-dependencies.html">зависимости полей</a> и обновляет варианты <code>state</code> при выборе <code>country</code>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">country</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Country
    <span class="token key atrule">type</span><span class="token punctuation">:</span> relation

<span class="token key atrule">state</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> State
    <span class="token key atrule">type</span><span class="token punctuation">:</span> relation
    <span class="token key atrule">dependsOn</span><span class="token punctuation">:</span> country
    <span class="token key atrule">modelScope</span><span class="token punctuation">:</span> filterStates
</code></pre></div><p>Значение <code>modelScope</code> <strong>filterStates</strong> соответствует методу <code>scopeFilterStates</code>, определённому в модели <code>State</code>. Аргумент <code>$model</code> (второй аргумент), передаваемый в <a href="./../../extend/database/model.html">область запроса модели</a>, позволяет получить выбранную страну и отфильтровать доступные варианты.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">scopeFilterStates</span><span class="token punctuation">(</span><span class="token variable">$query</span><span class="token punctuation">,</span> <span class="token variable">$model</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$countryId</span> <span class="token operator">=</span> <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">country_id</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;country_id&#39;</span><span class="token punctuation">,</span> <span class="token variable">$countryId</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="интеграция-с-relation-controller"><a href="#интеграция-с-relation-controller" class="header-anchor">#</a> Интеграция с Relation Controller</h2><p>Если контроллер реализует <a href="./../../extend/forms/relation-controller.html">поведение Relation Controller</a> и поле определено там, то оно будет отображаться с использованием этого определения. Установите свойство <code>useController</code> в false для отключения этой функциональности.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">countries</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Categories
    <span class="token key atrule">type</span><span class="token punctuation">:</span> relation
    <span class="token key atrule">useController</span><span class="token punctuation">:</span> <span class="token boolean important">false</span>
</code></pre></div><p>Свойство <code>controller</code> может использоваться для указания инлайн-конфигурации.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">products</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Products
    <span class="token key atrule">tab</span><span class="token punctuation">:</span> Products
    <span class="token key atrule">type</span><span class="token punctuation">:</span> relation
    <span class="token key atrule">controller</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Product
        <span class="token key atrule">list</span><span class="token punctuation">:</span> $/october/test/models/product/columns.yaml
        <span class="token key atrule">form</span><span class="token punctuation">:</span> $/october/test/models/product/fields.yaml
</code></pre></div>`,27))])}const v=o(u,[["render",d]]);export{f as __pageData,v as default};
